import sys

def main():
    d = sys.stdin.read().split()
    n = int(d[0])
    adj = [[] for _ in range(n)]
    for i in range(n - 1):
        u, v = int(d[1 + 2 * i]), int(d[2 + 2 * i])
        adj[u].append(v)
        adj[v].append(u)
    par = [-1] * n
    order = [0]
    for v in order:
        for w in adj[v]:
            if w != par[v]:
                par[w] = v
                order.append(w)
    hs = [[] for _ in range(n)]
    ss = [[] for _ in range(n)]
    for v in reversed(order):
        par_h = 1 + max(hs[v]) if hs[v] else 0
        if ss[v]:
            ss[v].sort(reverse=True)
            seq = max(j + f for j, f in enumerate(ss[v], 1))
        else:
            seq = 0
        if par[v] >= 0:
            hs[par[v]].append(par_h)
            ss[par[v]].append(seq)
        else:
            print(par_h, seq)

main()

