adj = [[] for _ in range(n)]
for i in range(n - 1):
    u, v = int(d[1 + 2 * i]), int(d[2 + 2 * i])
    adj[u].append(v)
    adj[v].append(u)

def solve(v, p, seq):
    vals = [solve(w, v, seq) for w in adj[v] if w != p]
    if not vals:
        return 0
    if not seq:
        return 1 + max(vals)
    return min(max(j + f for j, f in enumerate(perm, 1)) for perm in itertools.permutations(vals))

print(solve(0, -1, False), solve(0, -1, True))

